def sum_to_n(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def count_evens(nums):
    count = 0
    for x in nums:
        if x % 2 == 0:
            count += 1
    return count

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def max_of_list(nums):
    highest = nums[0]
    for val in nums[1:]:
        if val > highest:
            highest = val
    return highest

def add_item(lst, x):
    lst.append(x)
    return lst

def double_each(nums):
    res = []
    for x in nums:
        res.append(x * 2)
    return res

def range_sum(a, b):
    total = 0
    for i in range(a, b + 1):
        total += i
    return total
